int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n; cin >> n;
    vector<long long> p(n);
    for (auto &x : p) cin >> x;
    string unit; cin >> unit;
    const long long NONE = -1;
    // dp[s]: best settled population when the previous city has (s=1) or lacks (s=0) a staying unit.
    long long dp[2] = {0, NONE};
    for (int i = 0; i < n; i++) {
        long long nxt[2] = {NONE, NONE};
        bool has = unit[i] == '1';
        for (int prev = 0; prev < 2; prev++) {
            if (dp[prev] == NONE) continue;
            for (int mv = 0; mv < ((has && i) ? 2 : 1); mv++) {
                int stay = has && !mv;
                long long score = dp[prev] + ((i && (prev || mv)) ? p[i - 1] : 0);
                nxt[stay] = max(nxt[stay], score);
            }
        }
        dp[0] = nxt[0]; dp[1] = nxt[1];
    }
    long long ans = 0;
    for (int s = 0; s < 2; s++) if (dp[s] != NONE) ans = max(ans, dp[s] + (s ? p[n - 1] : 0));
