public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] p = new long[n];
        for (int i = 0; i < n; i++) p[i] = r.nextLong();
        String unit = r.next();
        final long NONE = -1;
        // dp[s]: best settled population when the previous city has (s=1) or lacks (s=0) a staying unit.
        long[] dp = {0, NONE};
        for (int i = 0; i < n; i++) {
            long[] nxt = {NONE, NONE};
            boolean has = unit.charAt(i) == '1';
            for (int prev = 0; prev < 2; prev++) {
                if (dp[prev] == NONE) continue;
                int moves = has && i > 0 ? 2 : 1;
                for (int mv = 0; mv < moves; mv++) {
                    int stay = has && mv == 0 ? 1 : 0;
                    long score = dp[prev] + (i > 0 && (prev == 1 || mv == 1) ? p[i - 1] : 0);
                    nxt[stay] = Math.max(nxt[stay], score);
                }
            }
            dp = nxt;
        }
        long ans = 0;
        for (int s = 0; s < 2; s++) if (dp[s] != NONE) ans = Math.max(ans, dp[s] + (s == 1 ? p[n - 1] : 0));
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	n := readInt()
	p := make([]int, n)
	for i := range p {
		p[i] = readInt()
	}
	unit := readToken()
	const none = -1
	// dp[s]: best settled population when the previous city has (s=1) or lacks (s=0) a staying unit.
	dp := [2]int{0, none}
	for i := 0; i < n; i++ {
		nxt := [2]int{none, none}
		has := unit[i] == '1'
		moves := 1
		if has && i > 0 {
			moves = 2
		}
		for prev := 0; prev < 2; prev++ {
			if dp[prev] == none {
				continue
			}
			for mv := 0; mv < moves; mv++ {
				stay := 0
				if has && mv == 0 {
					stay = 1
				}
				score := dp[prev]
				if i > 0 && (prev == 1 || mv == 1) {
					score += p[i-1]
				}
				nxt[stay] = max(nxt[stay], score)
			}
		}
		dp = nxt
	}
	ans := 0
	for s := 0; s < 2; s++ {
		if dp[s] != none {
			v := dp[s]
			if s == 1 {
				v += p[n-1]
			}
			ans = max(ans, v)
		}
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
